NEW_FILES = {'zoo_keeper/core/desk_screens.py': '"""What a desk\'s computer is showing, decided and painted in pure Python (Zoo 1.115.0; the factory\'s roadmap 148).\n\nThe walker\'s look review, 2026-10-19, on the factory\'s interiors: "Too sparse" -- "computer screens hsould be\non...bring life to this dead world". Every desk monitor `_surface_stock._monitor` built showed a dark plastic face\n(the ``screen`` finish, linear 0.02-0.03): a machine that is off, in every office of every level. This paints what a\n1997 office\'s machines were showing, so the screen can be lit (`prim_mesh.build_stock` builds it on a backlit\n``_Face`` material, which Lux\'s power cut turns off with the lights).\n\nTHE APPS, one 4:3 raster each -- invented software with Delco-flavoured names, never a real product, publisher or\nlogo (`tests/test_desk_screens.py` holds a denylist over every string painted):\n\n  * ``word``  -- a word processor, full screen: blue ground, white lines of text, a status row at the foot.\n  * ``sheet`` -- a spreadsheet: a pale grid with column letters and row numbers, figures in the cells, one cell\n    highlighted, a status row.\n  * ``desk``  -- a desktop: a teal ground, a grey program window with a title bar and a grid of icons, a second\n    window behind it.\n  * ``term``  -- a terminal: black, green lines of text and a block cursor.\n  * ``amber`` -- a bulletin board on an amber phosphor: a header, a menu, a prompt.\n  * ``stars`` -- a screensaver: black with stars, some brighter than others.\n\nThe text is never legible at a desk\'s distance and is not meant to be: lines are bars of ink in the app\'s colours,\nthe one or two words in the face (`pixel_type`\'s 8 px ``small`` face) are its title and its prompt. A screen is\npainted crisp, blurred once, then given the bar TV\'s tube: every other row dimmed, the corners darkened, a phosphor\'s\ncast (`crt_screens._tube`). Integer and float arithmetic only, rounded once: the same bytes on every build.\n\nWHICH APP a monitor shows is `pick_app`\'s: a hash of where the monitor stands on its top, so the stock\'s random\nstream -- which places every other item on the top -- is not drawn from. Desks of different builds show a mix;\nthe copies of one module (one stem, `kit.module_stem`) show its one app. Cold run 9349\'s office stood 9 desks on\n7 modules.\n"""\nfrom __future__ import annotations\n\nimport zlib\n\nfrom . import crt_screens as CS\nfrom . import pixel_type as pt\n\nAPPS = ("word", "sheet", "desk", "term", "amber", "stars")\n#: The raster\'s width; its height follows the screen\'s own aspect (`paint`).\nW = 128\nFACE = "small"\n\n#: Every string a screen paints, by app. Invented; the denylist test reads this.\nSTRINGS = {\n    "word": ("JAWN.DOC  PG 1 LN 4",),\n    "sheet": ("WOODERCALC", "READY", "ABCDEF"),\n    "desk": ("HOAGIE SHELL",),\n    "term": ("C:\\\\YO>",),\n    "amber": ("SCRAPPLE BBS", "MAIN MENU"),\n    "stars": (),\n}\n\nBLUE = (24, 40, 150)\nWHITE = (226, 228, 232)\nGREY = (172, 174, 178)\nDARK_GREY = (96, 98, 104)\nTEAL = (24, 128, 128)\nGREEN = (60, 220, 90)\nAMBER = (240, 168, 40)\nBLACK = (6, 8, 10)\nNAVY = (16, 24, 96)\nPAPER = (232, 232, 224)\nGRID = (150, 154, 166)\nHILITE = (40, 60, 170)\n\n\ndef _h(*k):\n    return zlib.crc32(",".join(str(v) for v in k).encode("utf-8")) & 0xFFFFFFFF\n\n\ndef pick_app(x, y, salt=""):\n    """The app the monitor standing at ``(x, y)`` (metres, its host\'s frame) shows: a hash of where it stands,\n    rounded to the millimetre, so the same desk always shows the same thing and the stock stream is untouched."""\n    return APPS[_h("desk_screen", salt, int(round(float(x) * 1000)), int(round(float(y) * 1000))) % len(APPS)]\n\n\ndef _text(img, s, x, y, rgb):\n    img.mask(pt.render(s, 1, FACE), x, y, rgb)\n\n\ndef _bars(img, x0, y0, x1, rows, pitch, rgb, key, min_frac=0.35):\n    """`rows` lines of text as bars of ink: each a run of words, each word a bar."""\n    for r in range(rows):\n        y = y0 + r * pitch\n        span = int((x1 - x0) * (min_frac + (1.0 - min_frac) * ((_h(key, "row", r) % 1000) / 1000.0)))\n        x = x0\n        w = 0\n        while x < x0 + span:\n            w = 3 + _h(key, r, x) % 9\n            img.rect(x, y, min(x + w, x0 + span), y + 2, rgb)\n            x += w + 2\n\n\ndef _word(img, key):\n    img.rect(0, 0, img.w, img.h, BLUE)\n    _bars(img, 4, 5, img.w - 6, (img.h - 16) // 4, 4, WHITE, key)\n    img.rect(0, img.h - 9, img.w, img.h, NAVY)\n    _text(img, STRINGS["word"][0], 2, img.h - 9, GREY)\n\n\ndef _sheet(img, key):\n    img.rect(0, 0, img.w, img.h, PAPER)\n    img.rect(0, 0, img.w, 9, HILITE)\n    _text(img, STRINGS["sheet"][0], 2, 0, WHITE)\n    cols, cw, rh, top, left = 6, (img.w - 10) // 6, 7, 18, 10\n    for c in range(cols):\n        _text(img, STRINGS["sheet"][2][c], left + c * cw + cw // 2 - 2, 9, DARK_GREY)\n    rows = (img.h - top - 10) // rh\n    for r in range(rows + 1):\n        img.rect(left, top + r * rh, img.w, top + r * rh + 1, GRID)\n    for c in range(cols + 1):\n        img.rect(left + c * cw, top, left + c * cw + 1, top + rows * rh, GRID)\n    for r in range(rows):\n        img.rect(1, top + r * rh + 2, 7, top + r * rh + 4, DARK_GREY)\n        for c in range(cols):\n            if _h(key, "cell", r, c) % 3:\n                w = 4 + _h(key, "w", r, c) % (cw - 6)\n                img.rect(left + (c + 1) * cw - 2 - w, top + r * rh + 3, left + (c + 1) * cw - 2,\n                         top + r * rh + 5, BLACK)\n    hr, hc = _h(key, "hr") % rows, _h(key, "hc") % cols\n    img.rect(left + hc * cw + 1, top + hr * rh + 1, left + (hc + 1) * cw, top + (hr + 1) * rh, HILITE)\n    img.rect(0, img.h - 9, img.w, img.h, GREY)\n    _text(img, STRINGS["sheet"][1], 2, img.h - 9, BLACK)\n\n\ndef _window(img, x0, y0, x1, y1, title, key):\n    img.rect(x0, y0, x1, y1, GREY)\n    img.rect(x0, y0, x1, y0 + 9, NAVY)\n    if title:\n        _text(img, title, x0 + 3, y0, WHITE)\n    img.rect(x0 + 2, y0 + 11, x1 - 2, y1 - 2, WHITE)\n    for r in range(2):\n        for c in range(4):\n            ix, iy = x0 + 8 + c * ((x1 - x0 - 12) // 4), y0 + 15 + r * 18\n            if iy + 10 < y1 - 2:\n                img.rect(ix, iy, ix + 8, iy + 8, (40 + _h(key, r, c) % 160, 60, 120 + _h(key, c) % 120))\n                img.rect(ix - 1, iy + 10, ix + 9, iy + 12, DARK_GREY)\n\n\ndef _desk(img, key):\n    img.rect(0, 0, img.w, img.h, TEAL)\n    _window(img, img.w // 2, 6, img.w - 6, img.h // 2 + 6, "", key + "b")\n    _window(img, 6, img.h // 4, img.w - 22, img.h - 8, STRINGS["desk"][0], key)\n\n\ndef _term(img, key):\n    img.rect(0, 0, img.w, img.h, BLACK)\n    rows = (img.h - 14) // 5\n    _bars(img, 3, 3, img.w - 20, rows, 5, GREEN, key, min_frac=0.15)\n    _text(img, STRINGS["term"][0], 3, img.h - 11, GREEN)\n    img.rect(3 + pt.width(STRINGS["term"][0], 1, FACE) + 1, img.h - 9, 3 + pt.width(STRINGS["term"][0], 1, FACE) + 6,\n             img.h - 3, GREEN)\n\n\ndef _amber(img, key):\n    img.rect(0, 0, img.w, img.h, BLACK)\n    _text(img, STRINGS["amber"][0], 4, 2, AMBER)\n    img.rect(4, 12, img.w - 4, 13, AMBER)\n    _text(img, STRINGS["amber"][1], 4, 16, AMBER)\n    _bars(img, 10, 28, img.w - 30, (img.h - 40) // 6, 6, AMBER, key, min_frac=0.3)\n    img.rect(4, img.h - 8, 10, img.h - 3, AMBER)\n\n\ndef _stars(img, key):\n    img.rect(0, 0, img.w, img.h, BLACK)\n    n = img.w * img.h // 60\n    for k in range(n):\n        x, y = _h(key, "x", k) % img.w, _h(key, "y", k) % img.h\n        v = 90 + _h(key, "v", k) % 166\n        # one pixel in three of the brightest is a 2 x 2 star: the blur takes a lone pixel down to a third\n        if v > 200:\n            img.rect(x, y, x + 2, y + 2, (v, v, v))\n        else:\n            img.set(x, y, (v, v, v))\n\n\nPAINTERS = {"word": _word, "sheet": _sheet, "desk": _desk, "term": _term, "amber": _amber, "stars": _stars}\n\n\ndef paint(spec):\n    """One app\'s screen from a planner\'s tile spec: ``{"kind": "desk_screen", "app", "w_m", "h_m"}``. Returns the\n    `vending_forms.Canvas` the card atlas packs. An unknown app raises, naming the apps there are."""\n    app = spec.get("app")\n    if app not in PAINTERS:\n        raise ValueError(f"desk_screens.paint: no app {app!r}; the apps are {\', \'.join(APPS)}")\n    w = W\n    h = max(24, int(round(W * float(spec["h_m"]) / float(spec["w_m"]))))\n    img = CS._Img(w, h, BLACK)\n    PAINTERS[app](img, f"{app}:{w}x{h}")\n    img.blur(1)\n    CS._tube(img)\n    return img.to_canvas()\n\n\ndef painted_strings():\n    """Every string any app paints, for the denylist test."""\n    return [s for app in APPS for s in STRINGS[app]]\n', 'tests/test_desk_screens.py': '"""A desk\'s computer is on (1.115.0; the factory\'s roadmap 148).\n\nThe walker\'s look review, 2026-10-19: "computer screens hsould be on...bring life to this dead world". Every desk\nmonitor showed the dark ``screen`` finish. `core.desk_screens` paints six 1997 office screens; `_surface_stock._monitor`\nputs an art quad in front of the glass; `plan_surface` names its app from where the monitor stands and asks the atlas\nfor every app; `prim_mesh.build_stock` builds the screens on a backlit `_Face` material.\n\nFAIL ON 1.114.1: there is no `desk_screens`, a monitor has no art quad, and an office top plans no tiles.\n"""\nimport random\nimport re\nimport zlib\n\nimport pytest\n\nfrom zoo_keeper.core import card_art as CA\nfrom zoo_keeper.core import desk_screens as DS\nfrom zoo_keeper.recipes import _surface_stock as SS\n\nSPEC = {"kind": "desk_screen", "w_m": 0.258, "h_m": 0.198}\n\n\ndef _lumas(c):\n    b = c.buf\n    return [0.2126 * b[3 * i] + 0.7152 * b[3 * i + 1] + 0.0722 * b[3 * i + 2] for i in range(c.w * c.h)]\n\n\n@pytest.mark.parametrize("app", DS.APPS)\ndef test_every_app_paints_the_same_bytes_every_time(app):\n    a = DS.paint(dict(SPEC, app=app))\n    b = DS.paint(dict(SPEC, app=app))\n    assert (a.w, a.h) == (b.w, b.h) and bytes(a.buf) == bytes(b.buf)\n    # 4:3-ish, as the screen it is painted for\n    assert a.w == DS.W and abs(a.h / a.w - SPEC["h_m"] / SPEC["w_m"]) < 0.01\n\n\ndef test_the_apps_differ_and_read_as_on():\n    """Six pictures, no two alike, each with something lit on it; the three with a lit ground (a blue page, a white\n    sheet, a teal desktop) bright over the whole face. The terminals and the screensaver are dark by nature -- a few\n    lines or stars on black -- and are held only to their brightest pixels."""\n    seen = set()\n    for app in DS.APPS:\n        c = DS.paint(dict(SPEC, app=app))\n        seen.add(zlib.crc32(bytes(c.buf)))\n        lum = _lumas(c)\n        assert max(lum) > 100.0, app\n        if app in ("word", "sheet", "desk"):\n            assert sum(lum) / len(lum) > 40.0, app\n    assert len(seen) == len(DS.APPS)\n\n\ndef test_an_unknown_app_refuses_by_name():\n    with pytest.raises(ValueError, match="the apps are"):\n        DS.paint(dict(SPEC, app="excel"))\n\n\n#: Real software, publishers and platforms of the time: none is painted.\nDENY = ("wordperfect", "word perfect", "microsoft", "excel", "lotus", "1-2-3", "quattro", "windows", "ms-dos",\n        "msdos", "ibm", "apple", "macintosh", "norton", "aol", "prodigy", "compuserve", "netscape", "after dark",\n        "flying toaster", "novell", "wordstar")\n\n\ndef test_no_real_product_is_painted():\n    """Whole words: SCRAPPLE is not APPLE."""\n    for s in DS.painted_strings():\n        low = s.lower()\n        assert not any(re.search(r"\\b" + re.escape(d) + r"\\b", low) for d in DENY), s\n\n\ndef test_the_card_atlas_paints_a_desk_screen():\n    c = CA.paint(dict(SPEC, app="term"))\n    assert bytes(c.buf) == bytes(DS.paint(dict(SPEC, app="term")).buf)\n\n\ndef test_where_a_monitor_stands_decides_its_app_and_spreads_them():\n    assert DS.pick_app(1.234, -0.5) == DS.pick_app(1.234, -0.5)\n    shown = {DS.pick_app(x * 0.37, y * 0.91) for x in range(12) for y in range(4)}\n    assert shown == set(DS.APPS)\n\n\ndef test_a_monitor_carries_a_screen_quad_in_front_of_its_glass():\n    prims = SS._monitor(random.Random(1))\n    art = [p for p in prims if p.get("tile") == SS.SCREEN_TILE]\n    assert len(art) == 1\n    q = art[0]\n    ys = {round(v[1], 6) for v in q["verts"]}\n    assert ys == {round(-0.19 - SS.DETAIL - SS.SCREEN_PROUD, 6)}\n    # more than 2 mm in front of the glass\'s face, so the coincident-face rule holds\n    assert SS.SCREEN_PROUD > 0.002\n    # the winding faces -Y: ascending X along the bottom edge\n    (x0, _y0, z0), (x1, _y1, z1) = q["verts"][0], q["verts"][1]\n    assert x1 > x0 and z1 == z0\n\n\ndef test_naming_the_screen_draws_nothing_from_the_stock_stream():\n    """The app comes from where the monitor stands, so every item placed after a monitor stays where it was."""\n    SS._screen_art()                      # builds with no stream at all\n    rng = random.Random(7)\n    before = rng.getstate()\n    SS._screen_art()\n    assert rng.getstate() == before\n\n\ndef test_an_office_top_lights_its_screens_from_one_atlas():\n    """Every office top with a monitor asks for every app\'s tile -- one image, one lit material for every desk -- and\n    each screen quad names the app where it stands."""\n    got = SS.plan_surface(random.Random(3), "office", -0.8, 0.8, -0.4, 0.4, 0.75, host_rgb=(0.4, 0.3, 0.2),\n                          facing=0.0, clear=0.8)\n    screens = [p for p in got["prims"] if str(p.get("tile", "")).startswith(SS.SCREEN_TILE + "_")]\n    assert screens, "an office top this size places a workstation"\n    assert sorted(got["tiles"]) == sorted(f"{SS.SCREEN_TILE}_{a}" for a in DS.APPS)\n    for q in screens:\n        assert re.fullmatch(SS.SCREEN_TILE + "_(" + "|".join(DS.APPS) + ")", q["tile"])\n\n\n#: Tops an office stock is planned on: a desk\'s (1.6 x 0.8), a small one, and a long cubicle work surface.\nTOPS = [(-0.8, 0.8, -0.4, 0.4), (-0.45, 0.45, -0.3, 0.3), (-1.2, 1.2, -0.35, 0.35)]\n\n\n@pytest.mark.parametrize("seed", range(10))\n@pytest.mark.parametrize("top", TOPS)\n@pytest.mark.parametrize("facing", [0.0, None])\ndef test_the_screens_move_nothing_else_on_a_top(monkeypatch, seed, top, facing):\n    """1.114.1\'s top, its screens added and nothing else moved: every other prim and every item where it was.\n\n    The screen\'s art stands SCREEN_PROUD in front of the glass, and the first build counted it in the monitor\'s\n    footprint: 2.5 mm deeper, every anchor and jitter drawn from the stream after it landed elsewhere, and in the kit\n    A/B against 1.114.1 a cubicle bank\'s top lost a workstation (six monitors to five). The 1.114.1 arm here is the\n    same planner with the art quad taken off the monitor."""\n    def plan():\n        return SS.plan_surface(random.Random(seed), "office", *top, 0.75, host_rgb=(0.4, 0.3, 0.2), facing=facing,\n                               clear=0.8)\n\n    got = plan()\n    real = SS._monitor\n    monkeypatch.setattr(SS, "_monitor", lambda rng: [p for p in real(rng) if p.get("tile") != SS.SCREEN_TILE])\n    was = plan()\n    assert [p for p in got["prims"] if not str(p.get("tile", "")).startswith(SS.SCREEN_TILE)] == was["prims"]\n    assert got["items"] == was["items"]\n'}
CHANGELOG = '## [1.115.0] - a desk\'s computer is on\n\n**The factory\'s roadmap 148.** The walker\'s look review, 2026-10-19, on the factory\'s interiors: "computer screens\nhsould be on...bring life to this dead world". Every monitor `_surface_stock._monitor` built showed the dark\n``screen`` finish -- a machine that is off -- on every desk and every cubicle bank\'s work surface, in every office of\nevery level.\n\n### Added\n- `core/desk_screens.py`: what a 1997 office machine is showing, painted in pure Python as the bar TV\'s ballgame is.\n  Six invented apps: a word processor (`JAWN.DOC`), a spreadsheet (`WOODERCALC`), a desktop (`HOAGIE SHELL`), a\n  terminal (`C:\\YO>`), an amber bulletin board (`SCRAPPLE BBS`) and a screensaver. Each is painted crisp, blurred once\n  and given the bar TV\'s tube (`crt_screens._tube`); its text is bars of ink with a title or a prompt, never legible\n  at a desk\'s distance. `pick_app` names the app from where the monitor stands on its top, a hash, so the stock\'s\n  stream is not drawn from. The copies of one module show its one app: cold run 9349\'s office stood 9 desks on 7\n  modules.\n- `recipes/_surface_stock.py`: `_monitor` carries an art quad `SCREEN_PROUD` (2.5 mm) in front of its glass and\n  `SCREEN_INSET` (6 mm) inside its edges. `plan_surface` names its tile and asks the atlas for every app, so every\n  monitor in a kit shares one image and one lit material.\n- `core/card_art.py`: `paint` dispatches a `desk_screen` tile.\n- `bpylayer/prim_mesh.py`: `build_stock` builds the screens into an atlas of their own on a backlit `_Face`\n  material, `M_StockScreen_<atlas>_Face`, at the bar TV\'s glow (`crt_forms.SCREEN_EMISSION` 1.5, `SCREEN_ALBEDO`\n  0.35). Lux\'s power cut finds it by name and turns it off with the lights. Every other tile is paint, as before.\n\n### Fixed before it shipped, and kept\n- The art quad was first counted in the monitor\'s footprint (`_local_rect`). That made the footprint 2.5 mm deeper,\n  and every anchor and jitter drawn after it landed elsewhere. In a kit A/B against 1.114.1 (one office desk and one\n  cubicle bank, built in Blender with cold run 9349\'s skins) the cubicle bank\'s top lost a workstation, six monitors\n  to five. The footprint now ignores the art. The A/B reads every 1.114.1 mesh unchanged, to a hash of its\n  positions, and adds one material, one image and one mesh: 2 triangles on the desk, 12 on the bank.\n\n### Changed\n- `build_stock`\'s docstring said an office top has no tiles; it has its screens since this release. Its solid prims\n  and their `stock_wear` stream are what they were, and the screens draw from `card_art` alone.\n\n### Cost\n- One draw for each module with a monitor, since its screens are one mesh, and one atlas for each kit. Level Factory\n  0.224.0 keeps each screen mesh where it stood and merges the rest of the desk into its room cell. The atlas\n  packer stacks the six apps in one column and leaves half of its 256 x 602 image empty.\n\n### Tests\n- `tests/test_desk_screens.py`, 74 in all, failing on 1.114.1, where there is no `desk_screens`:\n  - every app paints the same bytes every time;\n  - the six apps differ and read as on;\n  - an unknown app refuses by name;\n  - no real product is painted (a denylist, matched on whole words);\n  - the card atlas paints a desk screen;\n  - where a monitor stands decides its app, and spreads them;\n  - a monitor carries its quad in front of its glass;\n  - naming the screen draws nothing from the stock stream;\n  - an office top lights its screens from one atlas;\n  - the screens move nothing else on a top: 60 cases, 45 of which failed before the footprint fix.\n- `tests/test_flat_art.py`: finding 5\'s test held that only the card table plans art tiles. It is renamed\n  `test_the_cards_and_office_flavours_plan_tiles_and_no_other_flavour_does`, and holds the office to exactly the\n  six screen tiles and every other flavour to none.\n\n'
OLD_VERSION, NEW_VERSION = '1.114.1', '1.115.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
